let reportReference=today(),reportDetailDay='';
function weeklyReportPanel(){const r=SalonReports.report(db,reportReference),max=Math.max(...r.days.map(d=>d.count)),busy=r.days.filter(d=>d.count===max&&max>0).map(d=>d.day.slice(5)).join('、'),names=['周一','周二','周三','周四','周五','周六','周日'];
 const detail=r.days.find(d=>d.day===reportDetailDay),rows=detail?.rows||[];
 return `<div class="records-view"><div class="view-title"><div><span class="eyebrow">历史记录</span><h1>每周记录与总结</h1><p class="muted">${r.from} 至 ${r.to} · 按预约日期统计，跨天自动归入对应日期，不删除原记录。</p></div></div><section class="card"><div class="row"><button class="secondary" data-report-offset="-7">上一周</button><label>选择周内任一天<input id="report-reference" type="date" value="${reportReference}"></label><button class="secondary" data-report-offset="7">下一周</button><button class="secondary" data-report-today>本周</button></div><div class="statgrid"><div class="stat"><strong>${r.count}</strong>总预约</div><div class="stat"><strong>${r.done}</strong>已完成</div><div class="stat"><strong>${r.cancelled}</strong>已取消</div></div><div class="weekly-table-wrap"><table class="weekly-report-table"><thead><tr><th>日期</th><th>预约</th><th>完成</th><th>取消</th><th>完成服务时长</th><th>明细</th></tr></thead><tbody>${r.days.map((d,i)=>`<tr><td data-label="日期">${d.day}<br>${names[i]}</td><td data-label="预约">${d.count}</td><td data-label="完成">${d.done}</td><td data-label="取消">${d.cancelled}</td><td data-label="完成服务时长">${d.minutes}分钟</td><td data-label="明细"><button class="secondary" data-report-day="${d.day}" aria-label="查看${d.day}明细">查看明细</button></td></tr>`).join('')}</tbody></table></div><p class="muted">服务时长按已完成项目的预约时长累加，并非实际打卡工时；缺少金额时不计算营业额。</p></section><section class="card"><h2>本周简析</h2><p>${r.count?`共有${r.count}笔预约，已完成${r.done}笔，取消${r.cancelled}笔。${busy?'预约较多的日期是'+busy+'。':''}`:'本周暂无预约记录，先完成实际服务后再看统计。'}</p><p>${r.unfinished?'仍有'+r.unfinished+'笔预约未完成；过去日期的预约请核对到店及完成状态。':'本周没有未完成预约。'}</p>${r.staff.map(s=>`<p>${esc(s.name)}：${s.done}笔完成，累计${s.minutes}分钟。</p>`).join('')}</section>${detail?`<section class="card"><h2>${detail.day} 服务明细</h2>${rows.map(b=>`<div class="record"><span class="badge">${stateLabel[b.status]||esc(b.status)}</span><h3>${esc(b.name)} · ${esc(b.title)}</h3><p>${time(b.start)}—${time(b.start+b.duration)} · ${b.duration}分钟${b.hair==='short'?' · 短发':b.hair==='long'?' · 长发':''}</p>${lifecycleButtons(b)}</div>`).join('')||'<p>当天暂无记录。</p>'}</section>`:''}</div>`;
}
document.addEventListener('change',e=>{if(e.target.id==='report-reference'&&e.target.value){reportReference=e.target.value;reportDetailDay='';render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-report-offset],[data-report-today],[data-report-day]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-report-day')){openReportDetails(b.dataset.reportDay);return;}else{reportReference=b.hasAttribute('data-report-today')?today():addDay(reportReference,+b.dataset.reportOffset);reportDetailDay='';}render();});
function dailyReportDetails(day){const r=SalonReports.report(db,day),d=r.days.find(d=>d.day===day),rows=d?.rows||[];return `<div class="view-title"><div><h2>${esc(day)} 服务明细</h2><p class="muted">共${rows.length}笔预约 · 已完成${d?.done||0}笔 · 已取消${d?.cancelled||0}笔</p></div><button class="secondary" type="button" data-report-close>关闭</button></div>${rows.length?rows.map(b=>`<article class="record"><span class="badge">${stateLabel[b.status]||esc(b.status)}</span><h3>${esc(b.name||'未填写客户')} · ${esc(b.title||({cut:'洗剪吹',color:'染发',perm:'烫发',care:'护理'})[b.project]||'服务')}</h3><p>${time(b.start)}—${time(b.start+b.duration)} · ${b.duration}分钟${b.hair==='short'?' · 短发':b.hair==='long'?' · 长发':''}</p><p>理发师：${esc(db.staffSchedule?.staff.find(s=>s.id===b.staffId)?.name||'原记录未指定')}</p>${b.notes?`<p>备注：${esc(b.notes)}</p>`:''}${lifecycleButtons(b)}</article>`).join(''):'<div class="empty">当天暂无预约或服务记录。可选择表格中预约数大于0的日期查看。</div>'}`;}
function openReportDetails(day){if(view!=='merchant')return;document.querySelector('.report-detail-backdrop')?.remove();const modal=document.createElement('div');modal.className='modal-backdrop report-detail-backdrop';modal.innerHTML=`<section class="profile-modal report-detail" role="dialog" aria-modal="true" aria-label="${esc(day)}服务明细">${dailyReportDetails(day)}</section>`;document.body.appendChild(modal);const close=()=>{modal.remove();document.removeEventListener('keydown',onKey);},onKey=e=>{if(e.key==='Escape')close();};modal.querySelector('[data-report-close]').onclick=close;modal.onclick=e=>{if(e.target===modal)close();};document.addEventListener('keydown',onKey);modal.querySelector('[data-report-close]').focus();}